// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

contract Locals {
    enum Color { Red, Green, Blue }

    struct Point { uint256 x; uint256 y; }

    uint256 public total;

    // Exercises every value-type local, reference-type locals (which consume a
    // stack slot but are not decoded in M7b-2), and nested block + loop scopes.
    // With seed = 10:
    //   a=11, small=7, signed=-5, flag=true, who=0x..aa, hash=0x1122,
    //   color=Blue(2), tail=a+small=18, loop sum=36 (steps 11,12,13),
    //   inner=72 -> sum=108, total = a+sum+small+0 = 126.
    function compute(uint256 seed) public returns (uint256) {
        uint256 a = seed + 1;
        uint8 small = 7;
        int256 signed = -5;
        bool flag = true;
        address who = address(uint160(0xaa));
        bytes32 hash = bytes32(uint256(0x1122));
        Color color = Color.Blue;
        uint256 sum = 0;

        // Reference-type locals: each is a single memory pointer on the stack.
        uint256[] memory nums = new uint256[](2);
        nums[0] = a;
        string memory label = "hi";
        Point memory pt = Point(a, small);

        // A value-type local declared AFTER the reference locals: reading it
        // correctly proves stack-slot accounting counts the reference slots.
        uint256 tail = a + uint256(small);

        require(flag && color == Color.Blue);
        require(nums.length == 2 && bytes(label).length == 2 && pt.x == a);
        require(tail == 18);

        for (uint256 i = 0; i < 3; i = i + 1) {
            uint256 step = i + a;
            sum = sum + step;
        }

        {
            uint256 inner = sum * 2;
            sum = sum + inner;
        }

        total = a + sum + uint256(small) + uint256(int256(signed) + 5);
        total = total + uint256(uint160(who)) - uint256(uint160(who));
        total = total + uint256(hash) - uint256(hash);
        return total;
    }
}
